  function closeProvider(){if(!$('provider-options'))return;if(document.activeElement?.closest('#provider-options')&&!$('provider-options').hidden)$('provider-trigger').focus({preventScroll:true});$('provider-options').hidden=true;$('provider-trigger').setAttribute('aria-expanded','false');}
  function toggleProvider(){if(state.modelTesting)return;closeCatalog();closeModelDropdowns();const open=$('provider-options').hidden;$('provider-options').hidden=!open;$('provider-trigger').setAttribute('aria-expanded',String(open));if(open){positionFieldMenu($('provider-trigger'),$('provider-options'),280);}if(open)focusMenuOption($('provider-options').querySelector('[aria-selected="true"]')||$('provider-options').querySelector('button'),$('provider-options'));}
  function chooseProvider(provider){const d=state.modelDraft;if(!d||state.modelTesting||!providerSupports(provider,d.capability))return;if(d.provider!==provider){d.provider=provider;d.efforts=[];d.providerName=providers[provider][0];d.protocol=providers[provider][1];d.endpoint=providerEndpoint(provider,d.capability);d.keyConfigured=false;d.originalKeyConfigured=false;d.keyEntered=false;d.selectedId='';state.catalogQuery='';d.modelName='';d.modelId='';d.organization='';d.project='';d.thinking='不发送';d.thinkingBudget='';state.modelTestResult='';renderModelEditor();}else closeProvider();$('provider-trigger')?.focus();}
  function availableCatalog(){const d=state.modelDraft;const entries=window.DESKTOP_PROVIDER_CATALOG.providers[d.provider]||[];const matches=entries.filter(m=>m.capability===d.capability);return state.scenario==='catalog-many'?[...matches,...Array.from({length:80},(_,i)=>({id:`demo-${d.provider}-${d.capability==='文本'?'text':'image'}-scroll-${i+1}`,name:`滚动示例模型 ${String(i+1).padStart(2,'0')}`,capability:d.capability,efforts:[]}))]:matches;}
  function catalogOptions(){const d=state.modelDraft,q=state.catalogQuery.toLowerCase(),entries=availableCatalog().filter(m=>(m.name+' '+m.id).toLowerCase().includes(q));return entries.length?entries.map(m=>{const duplicate=state.models.some((saved,i)=>i!==state.modelEditing&&saved.provider===d.provider&&saved.modelId===m.id&&saved.endpoint===d.endpoint);return `<label class="catalog-row" role="option" aria-selected="${d.selectedId===m.id}"><input type="radio" name="catalog-model" data-catalog="${esc(m.id)}" ${d.selectedId===m.id?'checked':''} ${duplicate?'disabled':''} aria-label="${esc(m.name)}">${modelLogo({provider:d.provider,modelId:m.id})}<span class="grow"><strong>${esc(m.name)}</strong><small>${esc(m.id)}</small></span>${duplicate?'<small class="muted">已添加</small>':''}</label>`;}).join(''):'<div class="model-group-empty">没有匹配的模型</div>';}
  function catalogSummary(){const m=availableCatalog().find(m=>m.id===state.modelDraft.selectedId);return m?m.name:'请选择可用模型';}
  function catalogModels(){const d=state.modelDraft;return `<div class="field catalog-picker"><label id="catalog-label">可用模型</label><button id="catalog-trigger" class="model-select-trigger" aria-labelledby="catalog-label" aria-haspopup="listbox" aria-controls="catalog-dropdown" aria-expanded="false" data-action="toggle-catalog"><span id="catalog-selected-logo">${state.modelDraft.selectedId?modelLogo(state.modelDraft):''}</span><span id="catalog-summary" class="grow">${esc(catalogSummary())}</span>${icon('chevron-down')}</button><div id="catalog-dropdown" class="catalog-dropdown" hidden><input id="catalog-search" type="search" aria-label="搜索可用模型" placeholder="搜索模型名称或 ID…" value="${esc(state.catalogQuery)}"><div id="catalog-list" class="catalog-list" role="listbox" aria-labelledby="catalog-label" aria-multiselectable="false">${catalogOptions()}</div></div><small class="catalog-preview-note">设计示例；安装版显示供应商完整目录。每次配置一个模型。</small></div>`;}
  function closeCatalog(restore=false){const menu=$('catalog-dropdown');if(!menu)return;const focused=menu.contains(document.activeElement);menu.hidden=true;$('catalog-trigger').setAttribute('aria-expanded','false');if(restore||focused)$('catalog-trigger').focus({preventScroll:true});}
  function toggleCatalog(){if(state.modelTesting)return;const menu=$('catalog-dropdown'),open=menu.hidden;closeProvider();closeModelDropdowns();if(!open){closeCatalog(true);return;}menu.hidden=false;$('catalog-trigger').setAttribute('aria-expanded','true');positionCatalog();$('catalog-search').focus({preventScroll:true});}
  function positionFieldMenu(trigger,menu,maxHeight){const container=trigger.closest('.settings-body,.dialog-body'),bounds=container.getBoundingClientRect(),rect=trigger.getBoundingClientRect(),below=Math.max(0,bounds.bottom-rect.bottom-8),above=Math.max(0,rect.top-bounds.top-8);menu.style.position='fixed';menu.style.marginTop='0';menu.style.right='auto';menu.style.left=rect.left+'px';menu.style.width=rect.width+'px';menu.style.maxHeight=maxHeight+'px';const up=menu.offsetHeight>below&&above>below;menu.style.maxHeight=Math.min(maxHeight,up?above:below)+'px';menu.style.top=(up?rect.top-menu.offsetHeight-4:rect.bottom+4)+'px';menu.dataset.containerScroll=String(container.scrollTop);}
  function focusMenuOption(option,menu){if(!option)return;option.focus({preventScroll:true});const row=(option.closest('.catalog-row')||option).getBoundingClientRect(),bounds=menu.getBoundingClientRect();if(row.top<bounds.top+4)menu.scrollTop+=row.top-bounds.top-4;else if(row.bottom>bounds.bottom-4)menu.scrollTop+=row.bottom-bounds.bottom+4;}

  function positionCatalog(){positionFieldMenu($('catalog-trigger'),$('catalog-dropdown'),280);}

  function modelCandidates(){const d=state.modelDraft;if(!d)return [];if(d.provider==='custom')return [{...d}];const entry=availableCatalog().find(m=>m.id===d.selectedId);return entry?[{...d,modelId:entry.id,modelName:entry.name,efforts:entry.efforts||[]}]:[];}
  function validateModelDraft(){const candidates=modelCandidates();if(!candidates.length)return '请选择一个模型。';for(const m of candidates){const error=validateModel(m);if(error)return error;if(!m.keyConfigured)return '请填写 API Key。';if(state.models.some((saved,i)=>i!==state.modelEditing&&saved.provider===m.provider&&saved.endpoint===m.endpoint&&saved.modelId===m.modelId))return '此模型已添加，不能重复保存。';}return '';}
  function refreshModelActions(){const error=validateModelDraft(),busy=state.modelTesting;if($('model-edit-status'))$('model-edit-status').textContent=busy?`正在测试 ${state.testProgress}/${state.testTotal} · 可取消关闭配置框`:error||'点击保存模型后生效';document.querySelector('[data-action="save-model"]')?.toggleAttribute('disabled',busy||!!error);const test=document.querySelector('[data-action="test-model"]');if(test){test.disabled=busy||!!error;test.setAttribute('aria-busy',String(busy));test.innerHTML=busy?`${icon('loader-circle')}<span>测试中 ${state.testProgress}/${state.testTotal}</span>`:`${icon('plug-zap')}<span>测试连接</span>`;}if($('model-test-hint')){const count=modelCandidates().length;$('model-test-hint').textContent=`${count?'测试当前模型':'选择模型后测试'}：${state.modelDraft.capability==='图像'?'生成 1 张图片':'请求简短回复'}，可能产生供应商费用。设计预览仅模拟，不联网。`;}icons();}
  function lockTestFields(locked){document.querySelectorAll('.model-dialog input,.model-dialog select,.model-dialog summary,#provider-trigger,#catalog-trigger').forEach(el=>{if(locked){el.dataset.testWasDisabled=String(el.disabled||false);el.dataset.testWasTabindex=el.getAttribute('tabindex')??'';el.disabled=true;if(el.tagName==='SUMMARY')el.setAttribute('tabindex','-1');}else{el.disabled=el.dataset.testWasDisabled==='true';if(el.tagName==='SUMMARY'){if(el.dataset.testWasTabindex)el.setAttribute('tabindex',el.dataset.testWasTabindex);else el.removeAttribute('tabindex');}delete el.dataset.testWasDisabled;delete el.dataset.testWasTabindex;}});document.querySelector('.model-dialog')?.setAttribute('aria-busy',String(locked));}
  function startModelTest(){if(state.modelTesting||validateModelDraft())return;closeCatalog();closeProvider();const candidates=modelCandidates().map(m=>({...m})),session=state.modelSession,run=++state.testRun,scenario=state.scenario,results=[];state.modelTesting=true;state.testTotal=candidates.length;lockTestFields(true);function step(index){state.testProgress=index+1;refreshModelActions();state.testTimer=setTimeout(()=>{if(session!==state.modelSession||run!==state.testRun||!state.modelDraft)return;results.push({model:candidates[index],success:scenario!=='model-error'});if(index+1<candidates.length){step(index+1);return;}state.modelTesting=false;state.testTimer=null;lockTestFields(false);refreshModelActions();showModelTestResults(results);},2300);}step(0);document.querySelector('[data-action="cancel-model"]')?.focus();}
  function showModelTestResults(results){const editor=$('subdialog').querySelector('.model-dialog');editor.inert=true;editor.setAttribute('aria-modal','false');const failed=results.filter(r=>!r.success).length;$('subdialog').insertAdjacentHTML('beforeend',`<div id="model-result-layer" class="model-result-layer"><section class="small-dialog test-result-dialog" role="dialog" aria-modal="true" aria-label="测试结果"><header class="dialog-head"><h2>测试结果</h2><button class="icon-btn" data-action="close-test-result" aria-label="关闭测试结果">${icon('x')}</button></header><div class="dialog-body"><p class="test-summary" role="status">已测试 ${results.length} 个模型 · ${results.length-failed} 个成功${failed?` · ${failed} 个失败`:''}（模拟结果）</p><div class="test-results">${results.map(({model:m,success})=>`<div class="test-result-row"><span class="test-result-icon ${success?'success':'error-text'}">${icon(success?'circle-check':'circle-alert')}</span><div class="grow"><strong>${esc(m.modelName)}</strong><small class="path">${esc(m.modelId)} · ${esc(providers[m.provider][0])}</small><small class="path">${esc(m.endpoint)}</small><p class="${success?'success':'error-text'}">${success?'连接成功（示意）':'认证失败（401）。请检查此供应商的 Key 与端点。'}</p><small>${m.capability==='图像'?'文生图 · 1 张图片':'文本 · 简短回复'}</small></div></div>`).join('')}</div><p class="small muted">测试不会保存模型；返回配置后仍需点击保存模型。</p></div><footer class="dialog-foot"><button class="button primary" data-action="close-test-result">返回配置</button></footer></section></div>`);icons();}
  function closeModelTestResults(){const result=$('model-result-layer');if(!result)return;result.remove();const editor=$('subdialog').querySelector('.model-dialog');editor.inert=false;editor.setAttribute('aria-modal','true');syncModal();document.querySelector('[data-action="test-model"]')?.focus();}
  function finishModel(){const index=state.modelEditing,capability=state.modelDraft?.capability;clearTimeout(state.testTimer);state.testRun++;state.modelTesting=false;state.modelSession++;$('model-result-layer')?.remove();state.modelDraft=null;state.modelEditing=null;state.modelTestResult='';state.subReturn=null;hideSub();renderSettings('models');document.querySelector(index>=0?`[data-action="edit-model"][data-index="${index}"]`:`[data-action="add-model"][data-capability="${capability}"]`)?.focus();}
  function saveModels(){if(state.modelTesting)return;const error=validateModelDraft();if(error){$('model-edit-status').textContent=error;return;}if(state.scenario==='settings-save-error'){$('model-edit-status').textContent='保存失败：目录不可写。修改保留，已添加模型保持原配置。';return;}const candidates=modelCandidates().map(m=>{const {selectedId,originalKeyConfigured,keyEntered,...record}=m;record.contextLimit=record.contextLimit?String(parseContextLimit(record.contextLimit)):'';return record;});if(state.modelEditing>=0){state.models[state.modelEditing]=candidates[0];if(state.modelEditing===state.selectedModel)Object.assign(config,candidates[0]);}else state.models.push(...candidates);reconcileAgentEffort();updateModelPicker();finishModel();}
  function models(){return modelGroup('文本','文本模型')+modelGroup('图像','文生图模型');}
  function modelField(label,id,value,type='text',hint=''){return `<div class="field"><label for="model-${id}">${label}</label><input id="model-${id}" data-model="${id}" type="${type}" value="${esc(value||'')}">${hint?`<small>${hint}</small>`:''}</div>`;}
  function modelSelect(label,id,options,value,locked=false){return `<div class="field"><label for="model-${id}">${label}</label><select id="model-${id}" data-model="${id}" ${locked?'disabled':''}>${options.map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o||'请选择协议')}</option>`).join('')}</select>${locked?'<small>由供应商预设自动选择</small>':''}</div>`;}
  function validateModel(m){if(!m.protocol)return '请选择 OpenAI 或 Anthropic 协议。';if(!m.modelName.trim()||!m.modelId.trim())return '展示名称与模型 ID 必须填写。';if(m.provider==='custom'&&!m.providerName.trim())return '请填写自定义供应商名称。';try{const url=new URL(m.endpoint);if([...url.searchParams.keys()].some(k=>/^(api[-_]?key|key|token|access[-_]?token|secret|authorization)$/i.test(k)))throw Error();if(!['https:','http:'].includes(url.protocol)||url.username||url.password||(url.protocol==='http:'&&!['localhost','127.0.0.1','[::1]'].includes(url.hostname)))throw Error();}catch{return '请填写 HTTPS Base URL（本机模型允许回环 HTTP），地址不能含账号或密钥。';}if(m.contextLimit&&parseContextLimit(m.contextLimit)===null)return '上下文上限请输入正整数、128K 或 1M（十进制单位）。';if(m.protocol==='Anthropic'&&m.thinking==='enabled'&&(!Number.isInteger(Number(m.thinkingBudget))||Number(m.thinkingBudget)<1024||Number(m.thinkingBudget)>=Number(m.outputLimit)))return '思考预算需至少 1024，且小于输出上限。';return '';}
  function commitModel(){refreshModelActions();}
  function renderModelEditor(index=state.modelEditing){if(!state.modelDraft||state.modelEditing!==index){state.modelEditing=index;state.modelSession++;const base=index>=0?state.models[index]:{...modelCopy(),provider:'openai',providerName:'OpenAI',protocol:'OpenAI',endpoint:providers.openai[2],modelName:'',modelId:'',keyConfigured:false,enabled:true,capability:state.pendingModelCapability||'文本',thinking:'不发送',thinkingBudget:'',contextLimit:''};state.catalogQuery='';state.modelDraft={...base,originalKeyConfigured:base.keyConfigured,keyEntered:false,selectedId:base.provider==='custom'?'':base.modelId||''};state.modelTestResult='';}const d=state.modelDraft;let fields='';if(d.provider==='custom'){fields=`${modelField('供应商名称','providerName',d.providerName)}${modelSelect('协议','protocol',['','OpenAI','Anthropic'],d.protocol)}${modelField('展示名称','modelName',d.modelName)}${modelField('Base URL','endpoint',d.endpoint,'url','HTTPS；本机模型允许回环 HTTP。')}${modelField('模型 ID','modelId',d.modelId)}`;}const key=`<div class="field"><label for="demo-key">API Key</label><input id="demo-key" type="password" autocomplete="off" placeholder="${d.keyEntered?'已填写 · 待保存':d.keyConfigured?'已配置 · 留空保留原密钥':'请输入 API Key（设计预览请使用假 Key）'}"><small>仅用于此供应商；密钥不回填明文。</small></div>`;let extra='';if(d.provider==='custom'){extra=`<details class="advanced"><summary>高级配置</summary><div class="grid-two">${modelField('上下文上限（可选）','contextLimit',d.contextLimit,'text','例如 128K 或 1M；K=1000，M=1000000 token。')}</div></details>`;}showSub('配置模型',providerSelector(d)+fields+key+(d.provider==='custom'?extra:catalogModels())+`<div id="model-edit-status" class="editor-status" role="status"></div><p id="model-test-hint" class="small muted"></p>`,`<button class="button primary" data-action="save-model">保存模型</button><button class="button" data-action="test-model">${icon('plug-zap')} 测试连接</button><button class="button" data-action="cancel-model">取消</button>`);$('subdialog').querySelector('section').classList.add('model-dialog');refreshModelActions();}
  function eligibleModels(capability){return state.models.map((m,i)=>({m,i})).filter(({m})=>m.capability===capability&&m.enabled&&m.keyConfigured&&!validateModel(m));}
  const familyLogoProviders=['openai','anthropic','google','xai','kimi','qwen','tencent','bytedance'];
  function modelLogo(model){return model&&familyLogoProviders.includes(model.provider)?`<img class="model-logo ${model.provider==='openai'?'monochrome':''}" src="assets/models/${esc(model.provider)}.svg?v=0.9" alt="" aria-hidden="true">`:providerLogo(model?.provider||'custom');}
  function closeModelDropdowns(){const focusedMenu=document.activeElement?.closest('.model-options,#composer-model-menu');if(focusedMenu&&!focusedMenu.hidden)document.querySelector(`[aria-controls="${focusedMenu.id}"]`)?.focus({preventScroll:true});document.querySelectorAll('.model-options,#composer-model-menu').forEach(menu=>menu.hidden=true);document.querySelectorAll('[data-model-picker],#composer-model-trigger').forEach(trigger=>trigger.setAttribute('aria-expanded','false'));}
  function positionAgentMenu(trigger,menu){if(menu.classList.contains('model-options'))positionFieldMenu(trigger,menu,220);}
  function toggleModelDropdown(trigger){const menu=$(trigger.getAttribute('aria-controls')),open=menu.hidden;closeProvider();closeModelDropdowns();if(!open)return;menu.hidden=false;positionAgentMenu(trigger,menu);trigger.setAttribute('aria-expanded','true');const selected=menu.querySelector('[aria-selected="true"]:not([disabled]),[aria-checked="true"]:not([disabled])');focusMenuOption(selected||menu.querySelector('button:not([disabled])'),menu);}
  function agentModelSelect(label,name,capability){const value=state.pendingSettings[name]??config[name],entries=eligibleModels(capability),selected=state.models[Number(value)],missing=value!=='-1'&&!entries.some(({i})=>String(i)===value),placeholder=`请选择已添加的${capability==='图像'?'文生图':'文本'}模型`;return `<div class="field model-dropdown"><label id="${name}-label" for="${name}">${label}</label><button id="${name}" class="model-select-trigger" role="combobox" aria-labelledby="${name}-label" aria-haspopup="listbox" aria-controls="${name}-options" aria-expanded="false" data-model-picker="${name}" data-selected="${esc(value)}">${selected?modelLogo(selected):icon('box')}<span class="grow">${esc(missing?'原模型不可用 · 请重新选择':selected?.modelName||placeholder)}</span>${icon('chevron-down')}</button><div id="${name}-options" class="model-options" role="listbox" aria-label="${label}" hidden><button role="option" data-agent-choice="${name}" data-index="-1" aria-selected="${value==='-1'}">${icon('minus')}<span>${placeholder}</span></button>${missing?`<button role="option" disabled aria-selected="true">${modelLogo(selected)}<span>原模型不可用 · 请重新选择</span></button>`:''}${entries.map(({m,i})=>`<button role="option" data-agent-choice="${name}" data-index="${i}" aria-selected="${String(i)===value}">${modelLogo(m)}<span class="grow"><strong>${esc(m.modelName)}</strong><small>${esc(providers[m.provider]?.[0])} · ${esc(m.modelId)}</small></span>${String(i)===value?icon('check'):''}</button>`).join('')}</div>${entries.length?'':'<small>先在模型设置中添加模型。</small>'}</div>`;}
  function agentEfforts(){const selected=state.pendingSettings.agentDefaultText??config.agentDefaultText;return eligibleModels('文本').find(({i})=>i===Number(selected))?.m.efforts||[];}
  function agents(){const efforts=agentEfforts(),effort=state.pendingSettings.agentEffort??config.agentEffort;return `${agentModelSelect('默认模型','agentDefaultText','文本')}<div class="field"><label for="agentMode">默认模式</label><select id="agentMode" data-agent="agentMode">${['标准模式','计划模式'].map(m=>`<option ${(state.pendingSettings.agentMode??config.agentMode)===m?'selected':''}>${m}</option>`).join('')}</select></div><div class="field"><label for="agentEffort">默认思考强度</label><select id="agentEffort" data-agent="agentEffort" ${efforts.length?'':'disabled'}><option value="default" ${effort==='default'?'selected':''}>${efforts.length?'模型默认':'当前模型无可选档位'}</option>${efforts.map(o=>`<option value="${esc(o.value)}" ${effort===o.value?'selected':''}>${esc(o.label)}</option>`).join('')}</select></div>${agentModelSelect('默认审核模型','agentReview','文本')}${agentModelSelect('默认文生图模型','agentImage','图像')}`;}
  function reconcileAgentEffort(){for(const settings of [config,state.pendingSettings]){const index=Number(settings.agentDefaultText??config.agentDefaultText),model=state.models[index],effort=settings.agentEffort??config.agentEffort;if(!model||!model.enabled||!model.keyConfigured||!(model.efforts||[]).some(o=>o.value===effort)){if(settings===config||settings.agentEffort!==undefined)settings.agentEffort='default';}}}
  function commitAgent(name,value){if(['agentDefaultText','agentReview','agentImage'].includes(name)&&value!=='-1'&&!eligibleModels(name==='agentImage'?'图像':'文本').some(({i})=>String(i)===value))return;if(name==='agentEffort'&&value!=='default'&&!agentEfforts().some(o=>o.value===value))return;const effort=state.pendingSettings.agentEffort??config.agentEffort,nextEffort=(state.models[Number(value)]?.efforts||[]).some(o=>o.value===effort)?effort:'default';if(state.scenario==='settings-save-error'){state.pendingSettings[name]=value;if(name==='agentDefaultText')state.pendingSettings.agentEffort=nextEffort;state.liveMessage='更新失败 · 修改保留';}else{config[name]=value;delete state.pendingSettings[name];if(name==='agentDefaultText'){config.agentEffort=nextEffort;delete state.pendingSettings.agentEffort;}state.liveMessage='已自动更新（设计示意）';}renderSettings('agents');$(name)?.focus();}
  function avatarMarkup(){return `<div class="profile-avatar">${config.avatar?`<img src="${esc(config.avatar)}" alt="用户头像">`:esc(config.author.slice(0,1))}</div>`;}
  function user(){return `<div class="user-card">${avatarMarkup()}<div class="grow"><strong title="${esc(config.author)}">${esc(config.author)}</strong><small title="${esc(config.email||'本地创作者')}">${esc(config.email||'本地创作者')}</small></div><button class="icon-btn profile-edit-button" data-action="edit-profile" aria-label="编辑用户" title="编辑用户">${icon('pencil')}</button></div>`;}
  function renderProfileEditor(){cancelProfileRead();state.profileSession=(state.profileSession||0)+1;state.profileDraft={author:config.author,email:config.email,avatar:config.avatar};const d=state.profileDraft;showSub('编辑用户',`<div class="profile-editor-layout"><button class="profile-avatar-picker" data-action="choose-avatar" aria-label="选择头像"><span id="profile-avatar-preview">${profileAvatarPreview(d)}</span><span class="avatar-picker-caption">${icon('camera')} 点击更换头像<small>PNG / JPEG / WebP · 最大 2 MB</small></span></button><input id="profile-avatar" type="file" accept="image/png,image/jpeg,image/webp" hidden><div class="profile-editor-fields"><div class="field"><label for="profile-name">笔名</label><input id="profile-name" data-profile="author" value="${esc(d.author)}"></div><div class="field"><label for="profile-email">邮件</label><input id="profile-email" type="email" data-profile="email" value="${esc(d.email)}"><small>仅保存在本机，不用于登录或发送邮件。</small></div><div id="profile-error" class="field-error" role="status"></div></div></div>`,`<button class="button" data-action="cancel-profile">取消</button><button class="button primary" data-action="save-profile">保存</button>`);$('subdialog').querySelector('section').classList.add('profile-dialog');}
  function profileAvatarPreview(d){return d.avatar?`<img src="${esc(d.avatar)}" alt="待保存头像">`:`<span class="profile-avatar-initial">${esc(d.author.slice(0,1)||'作')}</span>`;}
  function validateProfile(){const d=state.profileDraft;return !d.author.trim()?'笔名不能为空。':d.email&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email)?'请输入有效邮件地址，或留空。':'';}
  function cancelProfileRead(){if(state.profileReader?.readyState===1)state.profileReader.abort();state.profileReader=null;state.profileLoading=false;state.profileRead=(state.profileRead||0)+1;}
