  function miniTheme(t){return `<div class="theme-preview theme-preview-${t}"><div class="mini-side"><img alt="" src="assets/seal-mark-${t==='ink'?'ink':'paper'}.svg"><b></b><b></b><b></b><b></b></div><div class="mini-chat"><div class="mini-bubble"></div><div class="mini-card"><b></b><b></b></div><div class="mini-input"></div></div><div class="mini-page"><span class="mini-title-placeholder" aria-hidden="true"></span><b></b><b></b><b></b><b></b><b></b><b></b></div></div>`;}
