  function shortcutList(){const rows=shortcutRows();return `<p class="shortcut-count small muted">${rows.length} 项命令</p><div class="shortcut-command-list" role="list">${rows.map(c=>{const keys=commandKeys(c),scope=c.scope==='text'?'所有文本编辑':c.scope==='global'?'应用':c.scope==='markdown'?'正文源码':c.scope==='composer'?'AI 输入':'普通输入';return `<div class="shortcut-command-row" role="listitem" data-command-row="${c.id}"><div class="shortcut-command-info"><strong title="${c.id}">${esc(c.label)}</strong><small>${esc(scope)} · 默认 ${esc(c[state.platform]||'未设置')}</small></div><div class="shortcut-bindings" role="group" aria-label="${esc(c.label)}的快捷键">${keys.length?keys.map((key,index)=>`<span class="shortcut-binding"><button class="binding-edit" data-action="record-key" data-command="${c.id}" data-binding-index="${index}" aria-label="编辑 ${esc(c.label)} 的 ${esc(key)}" ${c.locked?'disabled':''}><kbd>${esc(key)}</kbd></button>${c.locked?'':`<button class="binding-delete" data-action="delete-shortcut" data-command="${c.id}" data-binding-index="${index}" aria-label="删除 ${esc(c.label)} 的 ${esc(key)}" title="删除此快捷键">${icon('x')}</button>`}</span>`).join(''):'<span class="binding-empty">未设置</span>'}</div>${c.locked?'<span class="shortcut-locked">系统保留</span>':`<button class="icon-btn binding-add" data-action="record-key" data-command="${c.id}" data-binding-index="-1" aria-label="为 ${esc(c.label)} 添加快捷键" title="添加快捷键">${icon('plus')}</button>`}</div>`;}).join('')}</div>${rows.length?'':'<div class="search-empty">没有匹配的快捷键</div>'}`;}
