  function shortcutError(c,key,index){if(!key||!validShortcut(key))return '请按下完整的快捷键组合。';const canonical=canonicalKey(key),reserved=[...['Alt+F4','Cmd+Q','Cmd+Tab','Ctrl+Alt+Delete','Cmd+Space','Alt+Tab','Cmd+H','Cmd+Alt+H','Ctrl+F2'],...commands().filter(other=>other.locked).flatMap(other=>commandKeys(other))].map(canonicalKey);if(canonical.split(' ').some(chord=>reserved.includes(chord))||shortcutHits(c,key,index).some(hit=>hit.locked))return '此组合由系统保留，请选择其他按键。';if(shortcutHits(c,key,index).some(hit=>hit.id===c.id))return '此命令已有相同或前缀冲突的快捷键。';return '';}
