  function updateNavigation(){document.querySelectorAll('[data-action="navigate-back"]').forEach(b=>b.disabled=state.navIndex===0);document.querySelectorAll('[data-action="navigate-forward"]').forEach(b=>b.disabled=state.navIndex===state.navHistory.length-1);}
  function requestRevoke(action,index){state.revokeIndex=index!==undefined?Number(index):state.modelEditing??state.selectedModel;state.revokeKind=action==='delete-model'?'model':action==='disable-model'?'disable':'key';state.subReturn=!$('subdialog').hidden?'model':null;showSub(action==='clear-key'?'清除 API Key':action==='disable-model'?'停用模型':'删除模型','确认后取消此模型的在途请求，停止后续任务与重试；已生成候选和草稿保留。','<button class="button" data-action="close-sub">取消</button><button class="button danger" data-action="confirm-revoke">确认撤销</button>');}
  function closeSubEditor(){if($('shortcut-conflict-layer')){closeShortcutConflict();return;}if($('model-result-layer')){closeModelTestResults();return;}clearTimeout(state.testTimer);if(state.subReturn==='model'){state.subReturn=null;renderModelEditor();return;}if($('subdialog').querySelector('[aria-label="编辑用户"]')){finishProfile();return;}if($('subdialog').querySelector('[aria-label="配置模型"]')){finishModel();return;}hideSub();}
  document.addEventListener('input',event=>{const input=event.target;if(input.matches('.edit-surface .edit-demo')){state.editorDraft=input.value;updateLineGutter(input.closest('.edit-surface'));return;}if(input.id==='catalog-search'){state.catalogQuery=input.value;$('catalog-list').innerHTML=catalogOptions();icons();return;}if(input.matches('.recovery-editor')){state.recoveryText=input.value;return;}if(input.id==='composer-draft'){state.draft=input.value;return;}if(input.id==='shortcut-search'){state.shortcutQuery=input.value;$('shortcut-list').innerHTML=shortcutList();icons();return;}if(input.matches('[data-profile]')){state.profileDraft[input.dataset.profile]=input.value;$('profile-error').textContent=validateProfile();if(!state.profileDraft.avatar)$('profile-avatar-preview').innerHTML=profileAvatarPreview(state.profileDraft);return;}if(input.matches('[data-model]')){if(state.modelTesting)return;const d=state.modelDraft,key=input.dataset.model;state.modelTestResult='';if($('model-test-result'))$('model-test-result').innerHTML='';d[key]=input.value;if(['endpoint','protocol'].includes(key)){d.efforts=[];d.keyConfigured=false;d.originalKeyConfigured=false;d.keyEntered=false;$('demo-key').value='';}refreshModelActions();return;}if(input.id==='demo-key'){if(state.modelTesting)return;state.modelTestResult='';if($('model-test-result'))$('model-test-result').innerHTML='';state.modelDraft.keyEntered=!!input.value;state.modelDraft.keyConfigured=state.modelDraft.keyEntered||state.modelDraft.originalKeyConfigured;refreshModelActions();return;}if(input.matches('[data-config]')&&!input.closest('.reviewbar')){commitSetting(input.dataset.config,input.type==='checkbox'?input.checked:input.value);if(state.scenario==='settings-save-error'&&!document.querySelector('.live-error'))document.querySelector('.settings-body').insertAdjacentHTML('afterbegin',failureNotice());}});
  document.addEventListener('click',event=>{const input=event.target;if(!input.matches('[data-catalog]')||input.disabled||state.modelTesting||!state.modelDraft)return;state.modelDraft.selectedId=input.dataset.catalog;document.querySelectorAll('[data-catalog]').forEach(option=>{option.checked=option.dataset.catalog===state.modelDraft.selectedId;option.closest('.catalog-row').setAttribute('aria-selected',String(option.checked));});$('catalog-summary').textContent=catalogSummary();$('catalog-selected-logo').innerHTML=modelLogo(state.modelDraft);state.modelTestResult='';closeCatalog(true);refreshModelActions();});
  document.addEventListener('change',event=>{if(event.target.matches('[data-agent]')){commitAgent(event.target.dataset.agent,event.target.value);return;}if(event.target.id==='account-menu-theme'){if(!commitSetting('themeMode',event.target.checked?'ink':'paper'))toast('主题更新失败，修改保留，当前仍使用已确认主题。');renderAccountMenu();$('account-menu-theme').focus();return;}if(event.target.id!=='profile-avatar'||!state.profileDraft)return;const file=event.target.files[0];if(!file)return;cancelProfileRead();if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){$('profile-error').textContent='请选择不超过 2 MB 的 PNG / JPEG / WebP。';event.target.value='';return;}const session=state.profileSession,read=state.profileRead,reader=new FileReader();state.profileReader=reader;state.profileLoading=true;const current=()=>state.profileDraft&&state.profileSession===session&&state.profileRead===read&&!$('subdialog').hidden;reader.onload=()=>{if(!current())return;const preview=new Image();preview.onload=()=>{if(!current())return;state.profileLoading=false;state.profileDraft.avatar=String(reader.result);$('profile-avatar-preview').innerHTML=profileAvatarPreview(state.profileDraft);$('profile-error').textContent=validateProfile();};preview.onerror=()=>{if(current()){state.profileLoading=false;$('profile-error').textContent='图片无法解码，请重新选择有效图片。';}};preview.src=String(reader.result);};reader.onerror=()=>{if(current()){state.profileLoading=false;$('profile-error').textContent='头像读取失败，请重新选择图片。';}};reader.readAsDataURL(file);});
  document.addEventListener('click',event=>{if(!$('account-menu').hidden&&!event.composedPath().includes(document.querySelector('.sidebar-foot')))closeAccountMenu();});
  document.addEventListener('keydown',event=>{if(event.defaultPrevented||event.isComposing||event.keyCode===229)return;if($('account-menu').hidden)return;const fields=[...$('account-menu').querySelectorAll('input,button')];if(event.key==='Escape'){event.preventDefault();closeAccountMenu(true);}else if(['ArrowDown','ArrowUp','Home','End'].includes(event.key)){event.preventDefault();const i=fields.indexOf(document.activeElement),next=event.key==='Home'?0:event.key==='End'?fields.length-1:(i+(event.key==='ArrowDown'?1:-1)+fields.length)%fields.length;fields[next]?.focus();}else if(event.key==='Tab')closeAccountMenu();});
  document.addEventListener('click',event=>{const action=event.target.closest('button')?.dataset.action;if(['chapter','new-chat'].includes(action)){const page=action==='chapter'?'chapter':'chat';if(state.navHistory[state.navIndex]!==page){state.navHistory=state.navHistory.slice(0,state.navIndex+1);state.navHistory.push(page);state.navIndex++;updateNavigation();}}});
  $('preview-platform').addEventListener('change',event=>{if(state.page==='migration'&&state.migrationStep>=0&&state.migrationStep<5){event.target.value=state.platform;toast('迁移进行中，完成或取消后再切换预览平台。');return;}closeAppMenus();closeCatalog();if(!$('subdialog').hidden&&($('subdialog').querySelector('[data-action="confirm-key"],[data-action="confirm-reset-keys"],.directory-picker,.native-about'))){hideSub();state.recordingCommand='';}state.platform=event.target.value;$('desktop').dataset.platform=state.platform;renderPlatformMenu();if(sectionNames[state.page])renderSettings();else if(state.page==='create'||state.page==='chat-create')renderCreate(state.page==='chat-create');else if(state.page==='migration')renderMigration();});
